using sv_9d321e2d28ad46a4a7376bc505b561cd.Models;

namespace sv_9d321e2d28ad46a4a7376bc505b561cd.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> SeedData = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Margherita Pizza", "Classic Neapolitan pizza with fresh mozzarella, basil, and San Marzano tomatoes.", 30),
            new(2, "Pasta Carbonara", "Creamy Roman pasta with guanciale, egg yolk, pecorino, and black pepper.", 25),
            new(3, "Tiramisu", "Layered coffee-soaked ladyfingers with mascarpone cream and cocoa.", 45),
            new(4, "Risotto ai Funghi", "Creamy Arborio rice slowly cooked with porcini mushrooms and Parmesan.", 40),
        },
        [2] = new List<Recipe>
        {
            new(5, "Sushi Rolls", "Vinegared rice and fresh fish wrapped in nori with pickled ginger.", 60),
            new(6, "Ramen", "Rich pork bone broth with wheat noodles, chashu, and a soft-boiled egg.", 90),
            new(7, "Tempura", "Lightly battered and deep-fried shrimp and seasonal vegetables.", 35),
            new(8, "Miso Soup", "Dashi broth with white miso paste, tofu cubes, and wakame seaweed.", 15),
        },
        [3] = new List<Recipe>
        {
            new(9, "Tacos al Pastor", "Marinated pork on corn tortillas with pineapple, cilantro, and onion.", 50),
            new(10, "Guacamole", "Fresh avocado mashed with lime juice, cilantro, jalapeño, and tomato.", 10),
            new(11, "Enchiladas Rojas", "Corn tortillas filled with chicken, rolled and covered in red chili sauce.", 45),
            new(12, "Churros", "Fried dough pastry coated in cinnamon sugar, served with chocolate sauce.", 30),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        // Simulate a slow API call
        await Task.Delay(2000, cancellationToken);

        if (SeedData.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@using sv_9d321e2d28ad46a4a7376bc505b561cd.Models
@using sv_9d321e2d28ad46a4a7376bc505b561cd.Services
@rendermode InteractiveServer
@implements IDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation

<PageTitle>Recipes</PageTitle>

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_error</p>
        <button class="btn btn-outline-danger" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <p><em>Loading recipes...</em></p>
}
else
{
    @if (_isRefreshing)
    {
        <p><em>Refreshing…</em></p>
    }

    <h3>Recipes — Cuisine @CuisineId</h3>

    @if (_displayedRecipes.Count == 0)
    {
        <p>No recipes found for this cuisine.</p>
    }
    else
    {
        <ul>
            @foreach (var recipe in _displayedRecipes)
            {
                <li>
                    <strong>@recipe.Title</strong> — @recipe.Description
                    <em>(@recipe.PrepTimeMinutes min)</em>
                </li>
            }
        </ul>
    }
}

@code {
    [Parameter] public int CuisineId { get; set; }
    [SupplyParameterFromQuery(Name = "sort")] public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private List<Recipe> _displayedRecipes = new();
    private bool _isRefreshing;
    private string? _error;

    private CancellationTokenSource? _loadCts;
    private int _lastLoadedCuisineId;

    protected override async Task OnParametersSetAsync()
    {
        // Only reload data when the cuisine changes, not when sort changes
        if (_recipes is not null && CuisineId == _lastLoadedCuisineId)
        {
            ApplySort();
            return;
        }

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight request
        _loadCts?.Cancel();
        _loadCts?.Dispose();
        _loadCts = new CancellationTokenSource();
        var cts = _loadCts;

        _error = null;

        // If we already have data on screen, show refreshing indicator instead of full loading
        if (_recipes is not null)
        {
            _isRefreshing = true;
        }

        try
        {
            var results = await RecipeService.GetByCuisineAsync(CuisineId, cts.Token);

            // If cancelled during await, don't update state
            if (cts.Token.IsCancellationRequested)
                return;

            _recipes = results;
            _lastLoadedCuisineId = CuisineId;
            _isRefreshing = false;
            ApplySort();
        }
        catch (OperationCanceledException)
        {
            // Request was cancelled (user navigated to different cuisine or left page) — do nothing
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _isRefreshing = false;
            _error = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _isRefreshing = false;
            _error = "Something went wrong while loading recipes. Please try again.";
        }
    }

    private void ApplySort()
    {
        if (_recipes is null) return;

        _displayedRecipes = Sort?.ToLowerInvariant() switch
        {
            "newest" => _recipes.OrderByDescending(r => r.Id).ToList(),
            "popular" => _recipes.OrderBy(r => r.PrepTimeMinutes).ToList(),
            _ => _recipes.ToList(),
        };
    }

    private async Task RetryAsync()
    {
        _error = null;
        await LoadRecipesAsync();
    }

    public void Dispose()
    {
        _loadCts?.Cancel();
        _loadCts?.Dispose();
    }
}

